/* Card set: Broadway (generated from stage.csv by package_stage.py).
   (stage.js exceeds the push size limit, so the remaining cards live in stage-additions.js,
   which must stay directly after 'stage.js' in sets/manifest.js.) */
CardSets.register({"id":"stage","name":"Broadway","code":"STAGE","description":"415 cards from the Great White Way — the musicals, plays, theatres, creators, stars and songs of Broadway, from Show Boat and the Majestic to Hamilton. Original posters, Playbill covers and production stills throughout.","theme":{"primary":"#17101a","secondary":"#7a1f2b","artBackground":"#0d0810","artFit":"cover"},"pack":{"name":"Broadway","emblem":"🎭","skin":"stage"},"cards":[{"name":"The Phantom of the Opera","rarity":"chase","id":"the-phantom-of-the-opera","subtitle":"Musical","details":"Andrew Lloyd Webber's gothic romance opened in 1988 and ran 13,981 performances, the longest run in Broadway history.","image":"https://cdn.prod.website-files.com/60d34d273f7c4a820789864d/60f968738b7854c46e7e9670_Phantom%20of%20the%20Opera.jpg"},{"name":"Chicago","rarity":"chase","id":"chicago","subtitle":"Musical","details":"The 1996 revival framed a Jazz Age murder story as vaudeville, becoming Broadway's longest-running revival and longest-running American musical.","image":"https://cdn-imgix.headout.com/media/images/66e07f1dce2f156d5206918e3e662ee1-519.png?auto=format&"},{"name":"The Lion King","rarity":"chase","id":"the-lion-king","subtitle":"Musical","details":"Disney's 1997 staging used Julie Taymor's puppetry and masks to turn an animated film into Broadway's highest-grossing production.","image":"https://concertposter.org/wp-content/uploads/2020/08/LionKing-Bway-rop-768x1153.jpg"},{"name":"Wicked","rarity":"chase","id":"wicked","subtitle":"Musical","details":"Opening in 2003, this Oz prequel told the witches' untold story and grew into one of the defining blockbusters of the 21st century.","image":"https://cdn.craft.cloud/4027eea6-6e91-4e75-bd40-d01cbeb9c781/assets/shows/wicked-1000x1000_2024-05-30-171325_sxoj.jpg?fit=scale-down&width=2000&s=5lMfgbgYkWDT-7tanPMAMQgsyrCVx96Z934-SzaLB64"},{"name":"Hamilton","rarity":"chase","id":"hamilton","subtitle":"Musical","details":"Lin-Manuel Miranda's 2015 musical cast the Founding Fathers in hip-hop, winning the Pulitzer Prize and 11 Tony Awards.","image":"https://hellorpm.com/wp-content/uploads/2023/10/HAM-poster.png"},{"name":"Les Misérables","rarity":"chase","id":"les-mis-rables","subtitle":"Musical","details":"Boublil and Schönberg's 1987 adaptation of Victor Hugo's novel ran 6,680 performances in its sweeping tale of Jean Valjean.","image":"https://assets-global.website-files.com/5e408c0b483f3d5f9477a2bb/5e5815baefede435c536a732_les-miserables-main.jpg"},{"name":"Cats","rarity":"chase","id":"cats","subtitle":"Musical","details":"Andrew Lloyd Webber set T.S. Eliot's cat poems to music in 1982; the Jellicle ball ran 7,485 performances, once a Broadway record.","image":"https://shubert.nyc/media/1955/cats-broadway-052616.jpg"},{"name":"Rent","rarity":"chase","id":"rent","subtitle":"Musical","details":"Jonathan Larson's 1996 rock musical reimagined La bohème in the East Village and won the Pulitzer Prize for Drama.","image":"https://i0.wp.com/www.printmag.com/wp-content/uploads/2016/10/2a34d8_d5ff1d795b18450587d526b0af817c42mv2.jpg?resize=492%2C772&quality=89&ssl=1"},{"name":"A Chorus Line","rarity":"chase","id":"a-chorus-line","subtitle":"Musical","details":"Michael Bennett's 1975 audition musical let dancers tell their own stories, running 6,137 performances, once a Broadway record.","image":"https://static.greatbigcanvas.com/images/print_rolled_posterpaper/movie-goods/chorus-line-a-broadway-1975,mg0082298.jpg?max=800"},{"name":"The Book of Mormon","rarity":"chase","id":"the-book-of-mormon","subtitle":"Musical","details":"The South Park creators and Robert Lopez opened this irreverent missionary satire in 2011; it won nine Tonys, including Best Musical.","image":"https://616homes.com/wp-content/uploads/2016/06/book-of-mormon.jpg"},{"name":"Show Boat","rarity":"legendary","id":"show-boat","subtitle":"Musical","details":"Jerome Kern and Oscar Hammerstein II's 1927 saga on a Mississippi showboat marked the start of the modern American musical.","image":"https://www.mediastorehouse.com.au/sq/497/travel/boat-poster-1927-poster-original-broadway-production-jerome-kern-oscar-hammersteins-musical-boat-6620967.jpg.webp"},{"name":"Oklahoma!","rarity":"legendary","id":"oklahoma","subtitle":"Musical","details":"Rodgers and Hammerstein's first collaboration, from 1943, fused song, story and dance in ways that reshaped the Broadway musical.","image":"https://upload.wikimedia.org/wikipedia/en/b/b4/Musical1943-Oklahoma%21-OriginalPoster.jpg"},{"name":"West Side Story","rarity":"legendary","id":"west-side-story","subtitle":"Musical","details":"Bernstein, Sondheim, Laurents and Robbins moved Romeo and Juliet to rival New York street gangs for this 1957 landmark.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/West_Side_Story_1958_poster_ppmsca.15732.jpg/500px-West_Side_Story_1958_poster_ppmsca.15732.jpg"},{"name":"My Fair Lady","rarity":"legendary","id":"my-fair-lady","subtitle":"Musical","details":"Lerner and Loewe turned Shaw's Pygmalion into a 1956 hit starring Rex Harrison as Higgins and Julie Andrews as Eliza.","image":"https://upload.wikimedia.org/wikipedia/en/9/97/Myfairlady.jpg"},{"name":"The Sound of Music","rarity":"legendary","id":"the-sound-of-music","subtitle":"Musical","details":"The final Rodgers and Hammerstein musical opened in 1959, with Mary Martin as Maria von Trapp in Alpine Austria.","image":"https://upload.wikimedia.org/wikipedia/en/6/6b/Musical1959-SoundOfMusic-OriginalPoster.png"},{"name":"Fiddler on the Roof","rarity":"legendary","id":"fiddler-on-the-roof","subtitle":"Musical","details":"Tevye the milkman weighed tradition against change in Anatevka in 1964, the first musical to pass 3,000 performances.","image":"https://upload.wikimedia.org/wikipedia/en/d/dd/Fiddler_On_The_Roof_Playbill.jpg"},{"name":"Gypsy","rarity":"legendary","id":"gypsy","subtitle":"Musical","details":"Jule Styne, Stephen Sondheim and Arthur Laurents built this 1959 backstage classic around Ethel Merman's formidable Mama Rose.","image":"https://assets.playbill.com/editorial/_embeddedGallerySize/f3b0dd0540afe4379fa75a9949ff9d42-gypsy_1269030255.jpg"},{"name":"Cabaret","rarity":"legendary","id":"cabaret","subtitle":"Musical","details":"Kander and Ebb set this 1966 musical amid Berlin nightlife on the edge of collapse, hosted by Joel Grey's Emcee.","image":"https://upload.wikimedia.org/wikipedia/en/7/7f/Cabaret_1966_Musical_Poster.jpg"},{"name":"Annie","rarity":"legendary","id":"annie","subtitle":"Musical","details":"A plucky orphan and her dog Sandy carried this 1977 musical's Depression-era optimism into a permanent place in the repertoire.","image":"https://upload.wikimedia.org/wikipedia/en/f/f3/Annie_Musical_Poster.jpg"},{"name":"Evita","rarity":"legendary","id":"evita","subtitle":"Musical","details":"Andrew Lloyd Webber and Tim Rice charted Eva Perón's rise in 1979, giving Patti LuPone a star-making role as Evita.","image":"https://upload.wikimedia.org/wikipedia/en/d/d1/Pattiluponeevita.jpg"},{"name":"Sweeney Todd","rarity":"legendary","id":"sweeney-todd","subtitle":"Musical","details":"Stephen Sondheim's 1979 tale of a murderous Fleet Street barber paired grand guignol horror with a sweeping score.","image":"https://upload.wikimedia.org/wikipedia/en/2/2a/SweeneyToddLogo.jpg"},{"name":"Company","rarity":"legendary","id":"company","subtitle":"Musical","details":"Stephen Sondheim and Hal Prince's 1970 concept musical circled bachelor Bobby and the married couples surrounding him in Manhattan.","image":"https://assets.playbill.com/editorial/_defaultEnhancement/b1529ea1ad78c8445237c242ebe58713-companycover.jpg"},{"name":"The Music Man","rarity":"epic","id":"the-music-man","subtitle":"Musical","details":"Meredith Willson's 1957 portrait of a con man in small-town Iowa beat West Side Story to win the Best Musical Tony.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/The_Music_Man_poster%2C_1957.jpg/500px-The_Music_Man_poster%2C_1957.jpg"},{"name":"South Pacific","rarity":"epic","id":"south-pacific","subtitle":"Musical","details":"Rodgers and Hammerstein's 1949 wartime romance set on a Pacific island won the Pulitzer Prize for Drama.","image":"https://upload.wikimedia.org/wikipedia/en/6/6b/Musical1949-SouthPacific-OriginalPoster.jpg"},{"name":"The King and I","rarity":"epic","id":"the-king-and-i","subtitle":"Musical","details":"Rodgers and Hammerstein's 1951 musical of Anna and the King of Siam gave Yul Brynner the role that defined his career.","image":"https://upload.wikimedia.org/wikipedia/en/4/4d/King~I~OBP.jpeg"},{"name":"Guys and Dolls","rarity":"epic","id":"guys-and-dolls","subtitle":"Musical","details":"Frank Loesser filled this 1950 musical with Damon Runyon's gamblers, showgirls and Salvation Army missionaries in New York.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Guys-and-Dolls-Original-Poster.jpg/500px-Guys-and-Dolls-Original-Poster.jpg"},{"name":"Hello, Dolly!","rarity":"epic","id":"hello-dolly","subtitle":"Musical","details":"Jerry Herman's matchmaker musical opened in 1964 and made Dolly Levi the signature role of Carol Channing.","image":"https://upload.wikimedia.org/wikipedia/en/1/1f/DollyPlay.jpg"},{"name":"Funny Girl","rarity":"epic","id":"funny-girl","subtitle":"Musical","details":"This 1964 musical traced Fanny Brice's rise from Brooklyn to the Ziegfeld Follies and made Barbra Streisand a star.","image":"https://upload.wikimedia.org/wikipedia/en/b/bf/FunnyGirl1.jpg"},{"name":"Hair","rarity":"epic","id":"hair","subtitle":"Musical","details":"Billed as the American tribal love-rock musical, this 1968 show brought the hippie counterculture onto the Broadway stage.","image":"https://upload.wikimedia.org/wikipedia/en/b/b8/Hairposter.jpg"},{"name":"Grease","rarity":"epic","id":"grease","subtitle":"Musical","details":"This 1972 slice of 1950s high school ran 3,388 performances on rock-and-roll nostalgia before becoming a film phenomenon.","image":"https://images.squarespace-cdn.com/content/v1/5beb8df0da02bcaadac8821c/1553845549758-JUM1U4B7MT77PJWTS3F5/Grease+Window+Card.jpg?format=2500w"},{"name":"Jesus Christ Superstar","rarity":"epic","id":"jesus-christ-superstar","subtitle":"Musical","details":"Andrew Lloyd Webber and Tim Rice's 1971 rock opera retold the final days of Jesus through Judas's eyes.","image":"https://d7hftxdivxxvm.cloudfront.net?height=640&quality=80&resize_to=fit&src=https%3A%2F%2Fd32dm0rphc51dk.cloudfront.net%2FutSu7IX3uGzQML7bzkZYQA%2Flarge.jpg&width=340"},{"name":"Dreamgirls","rarity":"epic","id":"dreamgirls","subtitle":"Musical","details":"Michael Bennett staged this 1981 story of a Motown-inspired girl group's climb, fall and fight over its own sound.","image":"https://upload.wikimedia.org/wikipedia/en/6/6a/DreamGirls_Playbill_300.JPG"},{"name":"Into the Woods","rarity":"epic","id":"into-the-woods","subtitle":"Musical","details":"Sondheim and James Lapine wove familiar fairy tales together in 1987, then asked what followed happily ever after.","image":"https://upload.wikimedia.org/wikipedia/en/6/6a/Into_the_Woods_poster.jpg"},{"name":"Miss Saigon","rarity":"epic","id":"miss-saigon","subtitle":"Musical","details":"Boublil and Schönberg relocated Madame Butterfly to the Vietnam War in 1991, a saga famed for its helicopter scene.","image":"https://upload.wikimedia.org/wikipedia/en/5/5c/MissSaigonPoster.jpg"},{"name":"Beauty and the Beast","rarity":"epic","id":"beauty-and-the-beast","subtitle":"Musical","details":"Disney's first stage musical, in 1994, expanded its animated hit and set the template for the studio's Broadway era.","image":"https://upload.wikimedia.org/wikipedia/en/1/10/Beauty_and_the_Beast_%28cover_art%29_%E2%80%93_The_Broadway_Musical.jpg"},{"name":"Mamma Mia!","rarity":"epic","id":"mamma-mia","subtitle":"Musical","details":"ABBA's catalogue was woven into a Greek-island wedding story in 2001, proving the jukebox musical could conquer the world.","image":"https://upload.wikimedia.org/wikipedia/en/c/c3/Mammamiaposter.jpg"},{"name":"Hairspray","rarity":"epic","id":"hairspray","subtitle":"Musical","details":"John Waters's Baltimore tale became a 2002 musical about a teen dancer challenging segregation, winning Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/c/c1/Hairspray.jpg"},{"name":"The Producers","rarity":"epic","id":"the-producers","subtitle":"Musical","details":"Mel Brooks's 2001 musical about producers scheming with a flop won 12 Tony Awards, then a record for a single show.","image":"https://upload.wikimedia.org/wikipedia/en/b/be/Playbill.png"},{"name":"Jersey Boys","rarity":"epic","id":"jersey-boys","subtitle":"Musical","details":"This 2005 biography told the Four Seasons' rise from Newark street corners in the group's own tough, harmonised voice.","image":"https://upload.wikimedia.org/wikipedia/en/a/af/Jersey_Boys_opening_night_Playbill_cover.jpg"},{"name":"Carousel","rarity":"rare","id":"carousel","subtitle":"Musical","details":"Rodgers and Hammerstein's darkest classic, from 1945, gave fairground barker Billy Bigelow the anthem 'You'll Never Walk Alone.'","image":"https://upload.wikimedia.org/wikipedia/en/8/88/Musical1945-Carousel-OriginalPoster.jpg"},{"name":"Kiss Me, Kate","rarity":"rare","id":"kiss-me-kate","subtitle":"Musical","details":"Cole Porter's biggest hit, from 1948, staged a feuding divorced couple performing Shakespeare's The Taming of the Shrew.","image":"https://upload.wikimedia.org/wikipedia/en/0/01/Kiss_Me_Kate_1950_LP_Cover.jpg"},{"name":"On the Town","rarity":"rare","id":"on-the-town","subtitle":"Musical","details":"Bernstein, Comden and Green sent three sailors on 24 hours' leave racing through wartime New York in this 1944 musical.","image":"https://upload.wikimedia.org/wikipedia/en/3/30/On_the_Town_musical_poster_Adelphi_Theatre_1944_or_1945.jpg"},{"name":"Damn Yankees","rarity":"rare","id":"damn-yankees","subtitle":"Musical","details":"A Washington Senators fan bargained his soul for a pennant in this 1955 musical, with Gwen Verdon stealing scenes as Lola.","image":"https://upload.wikimedia.org/wikipedia/en/e/ee/Damn_yankees_1955.jpg"},{"name":"Bye Bye Birdie","rarity":"rare","id":"bye-bye-birdie","subtitle":"Musical","details":"Rock and roll shook a small Ohio town in this 1960 musical, an early showcase for Dick Van Dyke and Chita Rivera.","image":"https://upload.wikimedia.org/wikipedia/en/6/68/ByeByeBirdie1.jpg"},{"name":"How to Succeed in Business Without Really Trying","rarity":"rare","id":"how-to-succeed-in-business-without-really-trying","subtitle":"Musical","details":"Frank Loesser's satire of corporate ladder-climbing opened in 1961 and won the Pulitzer Prize for Drama.","image":"https://upload.wikimedia.org/wikipedia/en/f/f0/How_to_Succeed_in_Business_Without_Really_Trying_1961_Original_Cast_Recording.jpg"},{"name":"She Loves Me","rarity":"rare","id":"she-loves-me","subtitle":"Musical","details":"Bock and Harnick's 1963 romance paired two feuding Budapest shop clerks who were unknowingly writing love letters to each other.","image":"https://upload.wikimedia.org/wikipedia/en/7/74/SheLovesMePoster.JPG"},{"name":"1776","rarity":"rare","id":"1776","subtitle":"Musical","details":"This 1969 musical turned the debate over the Declaration of Independence into drama and beat Hair for the Best Musical Tony.","image":"https://upload.wikimedia.org/wikipedia/en/a/af/1776-musical.jpg"},{"name":"The Wiz","rarity":"rare","id":"the-wiz","subtitle":"Musical","details":"The Wonderful Wizard of Oz was retold through Black American music and culture in this 1975 hit, winner of seven Tonys.","image":"https://upload.wikimedia.org/wikipedia/en/e/e6/The_Wiz_%28original_cast_recording_-_album_cover%29.jpg"},{"name":"La Cage aux Folles","rarity":"rare","id":"la-cage-aux-folles","subtitle":"Musical","details":"Jerry Herman's 1983 drag-club farce balanced broad comedy with a plea for family, winning the Best Musical Tony.","image":"https://upload.wikimedia.org/wikipedia/en/9/9d/LaCagePoster.JPG"},{"name":"Follies","rarity":"rare","id":"follies","subtitle":"Musical","details":"Sondheim and Hal Prince reunited the fictional Weismann showgirls in 1971 for a lavish hit that famously lost money.","image":"https://upload.wikimedia.org/wikipedia/en/0/08/Follies_%281971_theater_poster%29.jpg"},{"name":"Ragtime","rarity":"rare","id":"ragtime","subtitle":"Musical","details":"This 1998 adaptation of E.L. Doctorow's novel braided ragtime, immigration and injustice across early 1900s America.","image":"https://upload.wikimedia.org/wikipedia/en/f/f6/Ragtime_%28musical%29_%28cast_recording_-_cover_art%29.jpg"},{"name":"Avenue Q","rarity":"rare","id":"avenue-q","subtitle":"Musical","details":"Puppets tackled rent, work and adulthood in this 2003 musical, which famously upset Wicked to win Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/d/d2/Image-AvenueQlogo.png"},{"name":"In the Heights","rarity":"rare","id":"in-the-heights","subtitle":"Musical","details":"Lin-Manuel Miranda's portrait of Washington Heights opened in 2008 and won the Tony Award for Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/0/0d/In_the_Heights.jpg"},{"name":"Spring Awakening","rarity":"rare","id":"spring-awakening","subtitle":"Musical","details":"Wedekind's 1891 story of German teenagers met Duncan Sheik's rock score in this 2006 musical, winner of eight Tonys.","image":"https://upload.wikimedia.org/wikipedia/en/4/41/Spring_Awakening_2006_album_cover.jpg"},{"name":"Kinky Boots","rarity":"rare","id":"kinky-boots","subtitle":"Musical","details":"Harvey Fierstein and Cyndi Lauper's 2013 musical saved a struggling shoe factory with drag performers, winning Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/1/15/Kinky_Boots_%28musical_poster%29.jpg"},{"name":"Fun Home","rarity":"rare","id":"fun-home","subtitle":"Musical","details":"Alison Bechdel's graphic memoir became this 2015 musical about memory, family and her father's secrets, winning Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/f/fb/FunHomeBroadwayPoster.jpg"},{"name":"Dear Evan Hansen","rarity":"rare","id":"dear-evan-hansen","subtitle":"Musical","details":"A fabricated friendship after a classmate's death drove this 2016 musical, winner of six Tonys including Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/9/91/DearEvanposter.png"},{"name":"Come From Away","rarity":"rare","id":"come-from-away","subtitle":"Musical","details":"This 2017 musical told how Gander, Newfoundland welcomed some 7,000 airline passengers stranded after the 9/11 attacks.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Schoenfeld_Theater_-_Come_From_Away_%2848193460457%29.jpg/500px-Schoenfeld_Theater_-_Come_From_Away_%2848193460457%29.jpg"},{"name":"Hadestown","rarity":"rare","id":"hadestown","subtitle":"Musical","details":"Anaïs Mitchell's folk opera retold Orpheus and Eurydice in a Depression-styled underworld, winning eight Tonys in 2019.","image":"https://upload.wikimedia.org/wikipedia/en/7/75/Hadestown_musical_poster.png"},{"name":"Waitress","rarity":"rare","id":"waitress","subtitle":"Musical","details":"Sara Bareilles scored this 2016 musical about Jenna, a pie-baking waitress in a small-town diner seeking a way out.","image":"https://upload.wikimedia.org/wikipedia/en/c/c7/Waitress_musical_Broadway_poster.jpg"},{"name":"Oh! Calcutta!","rarity":"rare","id":"oh-calcutta","subtitle":"Musical","details":"Kenneth Tynan's nude revue drew its card from sheer numbers: the 1976 revival ran 5,959 performances, eighth-longest in Broadway history.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d0/NYC-Oh_Calcutta-1981.jpg"},{"name":"Just in Time","rarity":"uncommon","id":"just-in-time","subtitle":"Musical","details":"Opened in 2025 at Circle in the Square, Bobby Darin's life unfolded as an intimate nightclub act, with Jonathan Groff originating the lead role.","image":"https://upload.wikimedia.org/wikipedia/en/7/79/JustInTimePoster.jpg"},{"name":"Anything Goes","rarity":"uncommon","id":"anything-goes","subtitle":"Musical","details":"Cole Porter's 1934 shipboard comedy mixed romance, disguises and tap-dancing sailors, and gave Ethel Merman a breakout starring role.","image":"https://i.pinimg.com/originals/fc/a6/d8/fca6d8c89d5166d04fa37e895761296e.jpg"},{"name":"Porgy and Bess","rarity":"uncommon","id":"porgy-and-bess","subtitle":"Musical","details":"The Gershwins' 1935 folk opera set life in Charleston's Catfish Row to a score blending opera, jazz and spirituals.","image":"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEimfCWmJWEMZrI89d78V_lzSwONpM3xFWCU8WLTm6lQr32pmdT36-6AKLEMydbILzMZcMk8adbILbqu-8MAaKLvz6pgalkuK9fMmB_9SzUXUWGuc6QdcjTJDTtVRHRnanBnr2gxGxF6ApZh/s400/Porgy-and-Bess-poster.jpg"},{"name":"Annie Get Your Gun","rarity":"uncommon","id":"annie-get-your-gun","subtitle":"Musical","details":"Irving Berlin's 1946 hit cast Ethel Merman as sharpshooter Annie Oakley and introduced 'There's No Business Like Show Business.'","image":"https://i.pinimg.com/736x/cf/c8/72/cfc8722fff5593139f99c81c0978bc7c.jpg"},{"name":"Wonderful Town","rarity":"uncommon","id":"wonderful-town","subtitle":"Musical","details":"Leonard Bernstein, Betty Comden and Adolph Green followed two Ohio sisters chasing work and love in 1953 Greenwich Village.","image":"https://image.tmdb.org/t/p/w440_and_h660_face/W4183ASz7WCa9zfAVWHiD0Q9Fl.jpg"},{"name":"Candide","rarity":"uncommon","id":"candide","subtitle":"Musical","details":"Leonard Bernstein's 1956 take on Voltaire stumbled at its premiere, then earned classic status for its witty, sparkling score.","image":"https://upload.wikimedia.org/wikipedia/en/5/5b/Candide_playbill.jpg"},{"name":"The Unsinkable Molly Brown","rarity":"uncommon","id":"the-unsinkable-molly-brown","subtitle":"Musical","details":"Meredith Willson's 1960 musical celebrated Molly Brown, a Colorado gold-rush heroine whose fortune never tamed her spirit.","image":"https://upload.wikimedia.org/wikipedia/en/b/bd/Unsinkable_molly_brown_1960.jpg"},{"name":"Camelot","rarity":"uncommon","id":"camelot","subtitle":"Musical","details":"Lerner and Loewe's 1960 Arthurian musical framed King Arthur's fading kingdom, a tale later tied to the Kennedy era.","image":"https://images.fineartamerica.com/images/artworkimages/medium/3/vintage-poster-camelot-1961-loc.jpg"},{"name":"A Funny Thing Happened on the Way to the Forum","rarity":"uncommon","id":"a-funny-thing-happened-on-the-way-to-the-forum","subtitle":"Musical","details":"Stephen Sondheim's 1962 farce borrowed from Roman playwright Plautus, with Zero Mostel scheming through the opening 'Comedy Tonight.'","image":"https://upload.wikimedia.org/wikipedia/en/8/8e/AFTHWF_original_Playbill.jpg"},{"name":"Oliver!","rarity":"uncommon","id":"oliver","subtitle":"Musical","details":"Lionel Bart's 1963 adaptation of Charles Dickens brought Oliver Twist to Broadway as a landmark British import of its era.","image":"https://upload.wikimedia.org/wikipedia/en/c/c1/Oliver%21_at_the_Imperial_Theatre_%28The_Broadway_version%29.jpg"},{"name":"Peter Pan","rarity":"uncommon","id":"peter-pan","subtitle":"Musical","details":"Mary Martin took flight in the 1954 stage version, and televised broadcasts turned the production into a childhood tradition.","image":"https://pimg.awa.io/v2/jacket/12de2cbe32f9e30c7093.w630.h630.v1694138142.jpg"},{"name":"Big River","rarity":"uncommon","id":"big-river","subtitle":"Musical","details":"Roger Miller gave Mark Twain's Huckleberry Finn a country-flavored score in 1985, and the river journey won Best Musical.","image":"https://static.greatbigcanvas.com/images/print_rolled_posterpaper/movie-goods/big-river-broadway-1985,mg0082301.jpg"},{"name":"Starlight Express","rarity":"uncommon","id":"starlight-express","subtitle":"Musical","details":"Andrew Lloyd Webber's 1987 racers were trains played on roller skates, a West End giant that became a Broadway curiosity.","image":"https://i.pinimg.com/originals/33/ad/72/33ad722b6e7562186ea1f1ad050ab407.jpg"},{"name":"Grand Hotel","rarity":"uncommon","id":"grand-hotel","subtitle":"Musical","details":"Set in a Berlin hotel in 1928 between two world wars, the 1989 musical drew lasting praise for Tommy Tune's staging.","image":"https://image.tmdb.org/t/p/original/eP67fumHlZhqSU9AV0yo2hPxyVV.jpg"},{"name":"Kiss of the Spider Woman","rarity":"uncommon","id":"kiss-of-the-spider-woman","subtitle":"Musical","details":"Kander and Ebb set their 1993 musical inside an Argentine prison, where Chita Rivera played the fantasy figure Aurora.","image":"https://d1m9cbe6bfhh6i.cloudfront.net/content/banner/common/page/banners/igsdjo.jpeg"},{"name":"Passion","rarity":"uncommon","id":"passion","subtitle":"Musical","details":"Stephen Sondheim's 1994 tale of obsessive love centered on the ailing Fosca and won Best Musical despite a notably brief run.","image":"https://upload.wikimedia.org/wikipedia/en/b/bc/Original_Passion_poster_art.jpg"},{"name":"Sunset Boulevard","rarity":"uncommon","id":"sunset-boulevard","subtitle":"Musical","details":"Andrew Lloyd Webber's 1994 musical cast Glenn Close as faded silent-film star Norma Desmond, ready for her close-up.","image":"https://cdn.prod.website-files.com/652e0f4548d2ced067643c32/652e0f4548d2ced067643cee_Sunset_Blvd-p-1080.webp"},{"name":"Titanic","rarity":"uncommon","id":"titanic","subtitle":"Musical","details":"Maury Yeston's 1997 musical told the liner's story through its passengers and crew and won Best Musical in the film's year.","image":"https://upload.wikimedia.org/wikipedia/en/2/21/Titanic_musical_Broadway_poster.jpg"},{"name":"Parade","rarity":"uncommon","id":"parade","subtitle":"Musical","details":"Jason Robert Brown and Alfred Uhry dramatized the Leo Frank case in 1998, a grave Southern story that won Best Score.","image":"assets/sets/compress/stage__parade.webp"},{"name":"Thoroughly Modern Millie","rarity":"uncommon","id":"thoroughly-modern-millie","subtitle":"Musical","details":"Sutton Foster led the 2002 flapper comedy as a small-town newcomer chasing big-city life, and the show won Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/4/4f/Modernmillieposter.jpg"},{"name":"Urinetown","rarity":"uncommon","id":"urinetown","subtitle":"Musical","details":"The 2001 satire built an entire dystopia around a tax on public toilets and wore its unlikely premise with pride.","image":"https://upload.wikimedia.org/wikipedia/en/7/70/Original_Broadway_poster_art_for_Urinetown.jpg"},{"name":"Caroline, or Change","rarity":"uncommon","id":"caroline-or-change","subtitle":"Musical","details":"Tony Kushner and Jeanine Tesori set their 2004 musical in a Louisiana basement in 1963, where a maid and a boy changed each other.","image":"https://youngbway.org/wp-content/uploads/2019/12/caroline-or-change-banner.jpg"},{"name":"Dirty Rotten Scoundrels","rarity":"uncommon","id":"dirty-rotten-scoundrels","subtitle":"Musical","details":"Two rival con men worked the French Riviera in the 2005 film adaptation, with Norbert Leo Butz stealing scene after scene.","image":"assets/sets/compress/stage__dirty-rotten-scoundrels.webp"},{"name":"The Light in the Piazza","rarity":"uncommon","id":"the-light-in-the-piazza","subtitle":"Musical","details":"Adam Guettel's 2005 romance followed an American mother and daughter through Florence, lit by a luminous, operatic score.","image":"https://upload.wikimedia.org/wikipedia/en/8/8f/TheLightInThePiazza.jpg"},{"name":"The Drowsy Chaperone","rarity":"uncommon","id":"the-drowsy-chaperone","subtitle":"Musical","details":"A devoted fan played his favorite 1928 cast album in 2006, and the creaky old musical sprang to life in his apartment.","image":"https://gimg.wolfgangs.com/m/large/ZZZ08295-PO/the-drowsy-chaperone-poster-jul-22-2008.jpg"},{"name":"Grey Gardens","rarity":"uncommon","id":"grey-gardens","subtitle":"Musical","details":"The 2006 musical turned the documentary about Edith and Edie Beale of East Hampton into a portrait of pride and decay.","image":"assets/sets/compress/stage__grey-gardens.webp"},{"name":"Xanadu","rarity":"uncommon","id":"xanadu","subtitle":"Musical","details":"The 2007 stage spoof rescued the roller-disco film flop with affection, turning a notorious misfire into a cult delight.","image":"https://static.greatbigcanvas.com/images/print_rolled_posterpaper/movie-goods/xanadu-broadway-,mg0083912.jpg"},{"name":"Rock of Ages","rarity":"uncommon","id":"rock-of-ages","subtitle":"Musical","details":"A jukebox trip through 1980s hair metal on the Sunset Strip, the 2009 musical paired arena anthems with a love story.","image":"assets/sets/compress/stage__rock-of-ages.webp"},{"name":"Memphis","rarity":"uncommon","id":"memphis","subtitle":"Musical","details":"Set in 1950s Memphis, the 2009 musical traced rock and roll radio's segregated beginnings and went on to win Best Musical.","image":"https://d2rbybg5ibx87t.cloudfront.net/images/14259/detail.jpg?1384550781"},{"name":"Catch Me If You Can","rarity":"uncommon","id":"catch-me-if-you-can","subtitle":"Musical","details":"Frank Abagnale Jr. sang through his cons in the 2011 film adaptation, scored in bright swing style by Marc Shaiman and Scott Wittman.","image":"https://upload.wikimedia.org/wikipedia/en/f/f0/Catch-me-if-you-can.jpg"},{"name":"A Gentleman's Guide to Love and Murder","rarity":"uncommon","id":"a-gentleman-s-guide-to-love-and-murder","subtitle":"Musical","details":"One distant heir plotted past eight doomed relatives in 2013, all eight played by Jefferson Mays, in a Best Musical winner.","image":"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiSXSJoFSCx-wUVe1FeFO3XMqNeqUlrE55MmNCr-BSJHQes645E7nOZG4YRaZ3aUOTTCGVZJgJRH184Ra2QE1sRUhSVrmBKaY-WL0loijnYrA-DZox1N1_KVaDy7Sx23_ngwpMqIYkZr1ho/s1600/Gentlemans_Guide_Horizontal_Art_Jefferson_Mays_1.jpg"},{"name":"Beautiful: The Carole King Musical","rarity":"uncommon","id":"beautiful-the-carole-king-musical","subtitle":"Musical","details":"The 2014 jukebox biography traced Carole King from Brooklyn teenage songwriter to the landmark album Tapestry.","image":"https://discover.ticketmaster.com.au/wp-content/uploads/2017/02/BCK015_BCK-Additional-OnSale-Tiles_Ticketmaster_2426x1365_Jan3012.jpg"},{"name":"Aladdin","rarity":"uncommon","id":"aladdin","subtitle":"Musical","details":"Disney's 2014 Arabian Nights adventure featured James Monroe Iglehart as a show-stopping Genie, its signature performance.","image":"assets/sets/compress/stage__aladdin.webp"},{"name":"Something Rotten!","rarity":"uncommon","id":"something-rotten","subtitle":"Musical","details":"Two Elizabethan brothers tried to invent the musical itself to outshine Shakespeare in the 2015 backstage comedy.","image":"https://d34hua95tpcqdg.cloudfront.net/55odvh44373dt8m5qnryhss84gm8"},{"name":"School of Rock","rarity":"uncommon","id":"school-of-rock","subtitle":"Musical","details":"Andrew Lloyd Webber's 2015 film adaptation built its band from real child musicians who played their instruments on stage.","image":"https://cdn11.bigcommerce.com/s-jvyxo7ln92/products/6330/images/1398/IMG_5347__06484.1687624814.386.513.jpg?c=1"},{"name":"Anastasia","rarity":"uncommon","id":"anastasia","subtitle":"Musical","details":"The 2017 stage version expanded the animated film's Romanov mystery into a journey from St. Petersburg to Paris.","image":"https://stsonstage.com/wp-content/uploads/2022/01/anastasia-2_src_1.jpeg"},{"name":"The Band's Visit","rarity":"uncommon","id":"the-band-s-visit","subtitle":"Musical","details":"An Egyptian police band stranded in a small Negev town anchored the 2017 musical, winner of 10 Tonys including Best Musical.","image":"https://blog.looktour.net/bk/wp-content/uploads/2017/10/TBV_P182_Logo_547x287_L1.jpg"},{"name":"Mean Girls","rarity":"uncommon","id":"mean-girls","subtitle":"Musical","details":"Tina Fey adapted her film for the 2018 musical, giving the Plastics songs as sharp as the original's one-liners.","image":"https://images.squarespace-cdn.com/content/v1/5de99669aa89ba7123976207/1666237912098-C9BAR1C4SZDN1R9QKIBX/MG_DigitalThumb+copyalt.jpg?format=1000w"},{"name":"Frozen","rarity":"uncommon","id":"frozen","subtitle":"Musical","details":"Disney's 2018 stage version rebuilt Elsa's ice palace in theatrical stagecraft around the film's songs, led by 'Let It Go.'","image":"https://o8xpu4zlffrzlztw.public.blob.vercel-storage.com/proxied/v1/403f2766c45b79d475ed1b2c7fed414c683cd433651e5f23edfc7fab83e7a0de-w1280"},{"name":"Beetlejuice","rarity":"uncommon","id":"beetlejuice","subtitle":"Musical","details":"The 2019 musical let the trickster ghost of the film run wild, and a devoted fandom gave the production a famous afterlife.","image":"https://townsquare.media/site/44/files/2024/02/attachment-Beetlejuice.jpg"},{"name":"Moulin Rouge!","rarity":"uncommon","id":"moulin-rouge","subtitle":"Musical","details":"Baz Luhrmann's Paris romance arrived supersized in 2019, stacking pop hits into a spectacle that won 10 Tonys including Best Musical.","image":"https://www.todaytix.com/_next/image?url=https%3A%2F%2Fimages.ctfassets.net%2F6pezt69ih962%2F55CyR4iu3hjcwApDhU3Gkj%2F68772c5e7509947e7b72ad8b2ceec5c3%2Flarge-MR_065_Banner_Resizing_2022_heart-portal_v01_1024x1024.jpg&w=384&q=75"},{"name":"Six","rarity":"uncommon","id":"six","subtitle":"Musical","details":"Henry VIII's six wives formed a pop group for the 2021 West End transfer, competing to tell the strongest story.","image":"https://images.milled.com/2020-03-05/E-RRYzxnsbE7BRFp/P0d0M6m98eS3.jpg"},{"name":"& Juliet","rarity":"uncommon","id":"and-juliet","subtitle":"Musical","details":"Juliet rewrote her ending in the 2022 jukebox musical, powered by Max Martin's catalogue of pop hits.","image":"https://cdn-imgix.headout.com/media/images/661d2a2c-0af8-4a3c-b315-48f5ef2d8304-1752990525265-293402.png"},{"name":"MJ the Musical","rarity":"uncommon","id":"mj-the-musical","subtitle":"Musical","details":"Set in a rehearsal room in 1992, the 2022 musical framed Michael Jackson's artistry around the making of a tour.","image":"https://images.milledcdn.com/2023-04-25/0Hdqujj-MoC0k7FX/5cmkY725unDc.jpeg"},{"name":"A Strange Loop","rarity":"uncommon","id":"a-strange-loop","subtitle":"Musical","details":"Michael R. Jackson's 2022 meta-musical looped a writer's doubts into songs and won both the Pulitzer Prize and Best Musical.","image":"https://didtheylikeit.com/wp-content/uploads/2022/04/AStrangeLoop300x400.png"},{"name":"Kimberly Akimbo","rarity":"uncommon","id":"kimberly-akimbo","subtitle":"Musical","details":"A teenager aging in fast-forward faced family, friendship and first love in the 2022 musical that won Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/a/a4/Kimberly_Akimbo_musical_logo.jpg"},{"name":"Hedwig and the Angry Inch","rarity":"uncommon","id":"hedwig-and-the-angry-inch","subtitle":"Musical","details":"The self-described internationally ignored song stylist reached Broadway in 2014, with Neil Patrick Harris in the wig.","image":"https://upload.wikimedia.org/wikipedia/en/6/60/Original_Hedwig_Poster_Art.jpg"},{"name":"Little Shop of Horrors","rarity":"uncommon","id":"little-shop-of-horrors","subtitle":"Musical","details":"Howard Ashman and Alan Menken's tale of a mild florist and a man-eating plant reached Broadway in a 2003 production.","image":"https://upload.wikimedia.org/wikipedia/en/7/79/LittleShopAlbum.jpg"},{"name":"The Color Purple","rarity":"uncommon","id":"the-color-purple","subtitle":"Musical","details":"Alice Walker's Celie found her own voice across decades of hardship in the 2005 musical adaptation of the novel.","image":"assets/sets/compress/stage__the-color-purple.webp"},{"name":"Next to Normal","rarity":"uncommon","id":"next-to-normal","subtitle":"Musical","details":"A suburban family weathered a mother's bipolar disorder in the 2009 rock musical, which went on to win the Pulitzer Prize.","image":"https://upload.wikimedia.org/wikipedia/en/7/72/Next_to_Normal_original_poster_art.jpg"},{"name":"Once","rarity":"uncommon","id":"once","subtitle":"Musical","details":"Two musicians met over a broken vacuum in a Dublin shop in the 2012 film adaptation, winner of Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/7/77/Once-musical-poster.jpg"},{"name":"Girl Crazy","rarity":"common","id":"girl-crazy","subtitle":"Musical","details":"The Gershwins headed west in 1930 with a cast that held both Ethel Merman's Broadway debut and a young Ginger Rogers.","image":"https://upload.wikimedia.org/wikipedia/en/8/84/Girl_Crazy_programme_ethel_merman.jpg"},{"name":"Of Thee I Sing","rarity":"common","id":"of-thee-i-sing","subtitle":"Musical","details":"The Gershwins' 1931 political satire about a presidential campaign became the first musical to win the Pulitzer Prize.","image":"https://upload.wikimedia.org/wikipedia/en/3/32/Of-Thee-I-Sing-FE.jpg"},{"name":"On Your Toes","rarity":"common","id":"on-your-toes","subtitle":"Musical","details":"Rodgers and Hart's 1936 comedy climaxed in George Balanchine's 'Slaughter on Tenth Avenue' ballet sequence.","image":"https://upload.wikimedia.org/wikipedia/en/e/e3/OnYourToes1.jpg"},{"name":"Babes in Arms","rarity":"common","id":"babes-in-arms","subtitle":"Musical","details":"Rodgers and Hart's 1937 kids-put-on-a-show tale introduced standards including 'My Funny Valentine' and 'The Lady Is a Tramp.'","image":"https://upload.wikimedia.org/wikipedia/en/8/81/Babes_in_Arms_Logo.png"},{"name":"Pal Joey","rarity":"common","id":"pal-joey","subtitle":"Musical","details":"Rodgers and Hart made a heel their hero in 1940, and the cynical nightclub tale gave Gene Kelly his breakout role.","image":"https://upload.wikimedia.org/wikipedia/en/a/ad/Pal_joey_1950.jpg"},{"name":"Lady in the Dark","rarity":"common","id":"lady-in-the-dark","subtitle":"Musical","details":"Kurt Weill, Moss Hart and Ira Gershwin put psychoanalysis on stage in 1941, framing the story through dream sequences.","image":"https://upload.wikimedia.org/wikipedia/en/e/ef/Lady_in_the_Dark_playbill_1942.jpg"},{"name":"One Touch of Venus","rarity":"common","id":"one-touch-of-venus","subtitle":"Musical","details":"Kurt Weill and Ogden Nash brought a statue to life in a department store in their 1943 whimsical romance.","image":"https://upload.wikimedia.org/wikipedia/en/e/e6/One_Touch_of_Venus.jpg"},{"name":"Allegro","rarity":"common","id":"allegro","subtitle":"Musical","details":"Rodgers and Hammerstein's experimental 1947 everyman story, directed by Agnes de Mille, followed one ordinary life from birth.","image":"https://upload.wikimedia.org/wikipedia/en/9/91/Musical1947-Allegro-OriginalPoster.jpg"},{"name":"Where's Charley?","rarity":"common","id":"where-s-charley","subtitle":"Musical","details":"Frank Loesser's first Broadway score powered the 1948 college farce, with Ray Bolger in the title role.","image":"https://upload.wikimedia.org/wikipedia/en/6/66/Where%27s_charley.png"},{"name":"Paint Your Wagon","rarity":"common","id":"paint-your-wagon","subtitle":"Musical","details":"Lerner and Loewe set their 1951 romance amid the California gold rush, among prospectors chasing sudden fortune.","image":"https://upload.wikimedia.org/wikipedia/en/2/29/Paint_your_wagon_1951.jpg"},{"name":"Can-Can","rarity":"common","id":"can-can","subtitle":"Musical","details":"Cole Porter set his 1953 comedy in Montmartre, where Gwen Verdon broke out in the Apache dance.","image":"https://upload.wikimedia.org/wikipedia/en/7/7b/Can-Can_Original_Cast_Recording.jpg"},{"name":"Fiorello!","rarity":"common","id":"fiorello","subtitle":"Musical","details":"The 1959 biography of Mayor Fiorello La Guardia achieved a rare double, winning both the Pulitzer Prize and the Tony.","image":"https://upload.wikimedia.org/wikipedia/en/c/c5/Fiorello_%28theater_poster%29.png"},{"name":"Bells Are Ringing","rarity":"common","id":"bells-are-ringing","subtitle":"Musical","details":"Judy Holliday played a telephone answering-service operator in the 1956 comedy by Jule Styne, Betty Comden and Adolph Green.","image":"https://upload.wikimedia.org/wikipedia/en/0/0c/BellsAreRinging.jpg"},{"name":"Call Me Madam","rarity":"common","id":"call-me-madam","subtitle":"Musical","details":"Irving Berlin wrote Ethel Merman a Washington ambassadorship in the 1950 satire, built squarely around her brass and timing.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Call_Me_Madam_-_Imperial_Theatre_%281950%29.jpg/500px-Call_Me_Madam_-_Imperial_Theatre_%281950%29.jpg"},{"name":"Finian's Rainbow","rarity":"common","id":"finian-s-rainbow","subtitle":"Musical","details":"Burton Lane and E.Y. Harburg sent an Irish leprechaun into the American South in their 1947 fantasy satire.","image":"https://upload.wikimedia.org/wikipedia/en/0/00/FinianPlaybill.JPG"},{"name":"I Do! I Do!","rarity":"common","id":"i-do-i-do","subtitle":"Musical","details":"A whole marriage unfolded with just two performers, Mary Martin and Robert Preston, in the intimate 1966 musical.","image":"https://upload.wikimedia.org/wikipedia/commons/5/55/Robert_Preston_Mary_Martin_Ido%21_Ido%21_1966.jpg"},{"name":"Applause","rarity":"common","id":"applause","subtitle":"Musical","details":"Lauren Bacall played Margo Channing in the 1970 musical version of All About Eve, a backstage tale of ambition and aging.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0f/Lauren_Bacall_Applause.jpg"},{"name":"Two Gentlemen of Verona","rarity":"common","id":"two-gentlemen-of-verona","subtitle":"Musical","details":"Shakespeare met rock music in the 1971 adaptation, which edged out Follies to win Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/e/ef/TwoGentlemen.JPG"},{"name":"Seussical","rarity":"common","id":"seussical","subtitle":"Musical","details":"Dr. Seuss's storybook worlds collided in the 2000 musical, a Broadway flop that became a staple of school stages.","image":"https://upload.wikimedia.org/wikipedia/en/f/f5/Seussical_%28logo%29.png"},{"name":"Me and My Girl","rarity":"common","id":"me-and-my-girl","subtitle":"Musical","details":"The 1986 revival dusted off a 1930s British romp, with Robert Lindsay leading the 'Lambeth Walk.'","image":"https://upload.wikimedia.org/wikipedia/en/2/2f/Meandmygirl.jpg"},{"name":"Brigadoon","rarity":"common","id":"brigadoon","subtitle":"Musical","details":"Lerner and Loewe's 1947 romance found a Scottish village that appears for one day once every hundred years.","image":"https://upload.wikimedia.org/wikipedia/en/c/c9/Brigadoon_1947_a.JPG"},{"name":"The Pajama Game","rarity":"common","id":"the-pajama-game","subtitle":"Musical","details":"Labor strife hit a pajama factory in the 1954 comedy, which carried Bob Fosse's first choreography credit.","image":"https://upload.wikimedia.org/wikipedia/en/f/ff/ThePajamaGame1954.jpg"},{"name":"Promises, Promises","rarity":"common","id":"promises-promises","subtitle":"Musical","details":"Burt Bacharach and Hal David scored Neil Simon's office romances in 1968, bringing a pop-radio sound to Broadway.","image":"https://upload.wikimedia.org/wikipedia/en/e/e9/Promises_Promises_Revival_Logo.png"},{"name":"Ain't Misbehavin'","rarity":"common","id":"ain-t-misbehavin","subtitle":"Musical","details":"The 1978 revue celebrated Fats Waller's Harlem, building a full evening from his stride piano songs.","image":"https://upload.wikimedia.org/wikipedia/en/0/09/Aintmisbehavin.jpg"},{"name":"Nine","rarity":"common","id":"nine","subtitle":"Musical","details":"Federico Fellini's film 8 1/2 became a musical in 1982, staged by Tommy Tune with Raul Julia as the director Guido.","image":"https://upload.wikimedia.org/wikipedia/en/a/ac/NinePlaybill.jpg"},{"name":"Falsettos","rarity":"common","id":"falsettos","subtitle":"Musical","details":"William Finn charted a chosen, complicated family in the age of AIDS in his 1992 two-part musical saga.","image":"https://upload.wikimedia.org/wikipedia/en/5/5f/Falsettos.jpg"},{"name":"Spamalot","rarity":"common","id":"spamalot","subtitle":"Musical","details":"Monty Python and the Holy Grail was lovingly ripped off for the 2005 stage spoof, which won Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/d/d3/Spamalot_poster.jpg"},{"name":"Pippin","rarity":"common","id":"pippin","subtitle":"Musical","details":"Stephen Schwartz and Bob Fosse sent a restless prince searching for his corner of the sky in the 1972 musical.","image":"https://upload.wikimedia.org/wikipedia/en/a/ab/Pippinalbum.jpg"},{"name":"Sunday in the Park with George","rarity":"common","id":"sunday-in-the-park-with-george","subtitle":"Musical","details":"Sondheim and James Lapine stepped inside Georges Seurat's pointillist painting in the 1984 Pulitzer-winning musical.","image":"https://upload.wikimedia.org/wikipedia/en/6/6e/Sunday_in_the_Park_Original_Playbill.jpg"},{"name":"Man of La Mancha","rarity":"common","id":"man-of-la-mancha","subtitle":"Musical","details":"Don Quixote told his tale from a prison cell in the 1965 musical that introduced 'The Impossible Dream.'","image":"https://upload.wikimedia.org/wikipedia/en/9/90/Playbill_Man_of_La_Mancha.jpg"},{"name":"42nd Street","rarity":"common","id":"42nd-street","subtitle":"Musical","details":"The 1980 backstage musical followed a chorus girl's overnight rise during a Depression-era production, to 'Lullaby of Broadway.'","image":"https://upload.wikimedia.org/wikipedia/en/4/4f/42ndStreetLP.jpg"},{"name":"Sweet Charity","rarity":"common","id":"sweet-charity","subtitle":"Musical","details":"Bob Fosse and Cy Coleman built the 1966 musical around Gwen Verdon as a dance-hall hostess hoping for love.","image":"https://upload.wikimedia.org/wikipedia/en/6/66/Sweet_charity_1966_a.JPG"},{"name":"Merrily We Roll Along","rarity":"common","id":"merrily-we-roll-along","subtitle":"Musical","details":"Sondheim told a friendship story backwards in 1981; the production flopped, and the score grew into a classic.","image":"https://upload.wikimedia.org/wikipedia/en/6/6e/MerrilyWeRollAlong.jpg"},{"name":"Anyone Can Whistle","rarity":"common","id":"anyone-can-whistle","subtitle":"Musical","details":"Sondheim and Arthur Laurents' 1964 experiment closed after nine performances and marked Angela Lansbury's musical debut.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7d/Remick-Lansbury-Guardino-Greene.jpg"},{"name":"Chess","rarity":"uncommon","id":"chess","subtitle":"Musical","details":"Tim Rice and ABBA's writers set Cold War intrigue at a chess championship in 1988; the 2025 revival ran 249 performances, with five Tony nominations.","image":"https://static.greatbigcanvas.com/images/print_framedprint_blackprint/movie-goods/chess-broadway-1988,mg0082299.jpg"},{"name":"Carrie","rarity":"common","id":"carrie","subtitle":"Musical","details":"Stephen King's prom night became the 1988 musical remembered as the most famous flop in Broadway history.","image":"https://upload.wikimedia.org/wikipedia/en/7/7f/Carrie_the_Musical_Poster.jpg"},{"name":"Side Show","rarity":"common","id":"side-show","subtitle":"Musical","details":"The 1997 musical sang the story of the conjoined Hilton twins and grew into a cult favorite with a devoted following.","image":"https://upload.wikimedia.org/wikipedia/en/9/99/Side_Show_1997_Poster.jpg"},{"name":"The Wild Party","rarity":"common","id":"the-wild-party","subtitle":"Musical","details":"Andrew Lippa's 2000 musical let a Prohibition party spiral gorgeously out of control over one long night.","image":"https://upload.wikimedia.org/wikipedia/en/3/30/WildPartyCD.jpg"},{"name":"Sophisticated Ladies","rarity":"common","id":"sophisticated-ladies","subtitle":"Musical","details":"Duke Ellington's songbook filled the 1981 revue, fronted by tap star Gregory Hines and a full jazz orchestra.","image":"https://upload.wikimedia.org/wikipedia/en/b/b6/SophisticatedLadies.JPG"},{"name":"My One and Only","rarity":"common","id":"my-one-and-only","subtitle":"Musical","details":"A 1983 romance built from Gershwin songs starred Tommy Tune and Twiggy, pairing vintage tunes with exuberant tap dancing.","image":"https://upload.wikimedia.org/wikipedia/en/b/b2/MyOneAndOnly.jpg"},{"name":"They're Playing Our Song","rarity":"common","id":"they-re-playing-our-song","subtitle":"Musical","details":"Marvin Hamlisch and Carole Bayer Sager turned their own romance into the 1979 musical about two songwriters in love.","image":"https://upload.wikimedia.org/wikipedia/en/c/c7/TheyrePlayingOurSong.jpg"},{"name":"Seesaw","rarity":"common","id":"seesaw","subtitle":"Musical","details":"Cy Coleman's 1973 musical paired two New Yorkers from very different worlds in an unlikely romance.","image":"https://upload.wikimedia.org/wikipedia/en/7/78/SeesawCD.jpg"},{"name":"Woman of the Year","rarity":"common","id":"woman-of-the-year","subtitle":"Musical","details":"Kander and Ebb's 1981 musical matched Lauren Bacall against Harry Guardino in a battle-of-the-sexes comedy.","image":"https://upload.wikimedia.org/wikipedia/en/7/79/WomanOfTheYearLP.jpg"},{"name":"Dancin'","rarity":"common","id":"dancin","subtitle":"Musical","details":"Bob Fosse built the 1978 showcase with no plot at all, letting pure dance carry the entire evening.","image":"https://upload.wikimedia.org/wikipedia/en/d/d7/Dancin%27OriginalBroadwayPoster.jpg"},{"name":"Big Fish","rarity":"common","id":"big-fish","subtitle":"Musical","details":"A father's tall tales came to life in the 2013 film adaptation, as a son sorted myth from memory.","image":"https://upload.wikimedia.org/wikipedia/en/b/b0/Big_Fish_playbill.jpg"},{"name":"Rocky","rarity":"common","id":"rocky","subtitle":"Musical","details":"Sylvester Stallone's boxer sang in the 2014 adaptation, and its final fight spilled across the Winter Garden stage.","image":"https://upload.wikimedia.org/wikipedia/en/8/81/Rocky_the_Musical.jpg"},{"name":"Tootsie","rarity":"common","id":"tootsie","subtitle":"Musical","details":"David Yazbek scored the 2019 comedy about an out-of-work actor who found success disguised as a woman.","image":"https://upload.wikimedia.org/wikipedia/en/3/38/Tootsie_Playbill.png"},{"name":"Pretty Woman","rarity":"common","id":"pretty-woman","subtitle":"Musical","details":"The film's romance reached Broadway in 2018, retold with a pop score by singer-songwriter Bryan Adams.","image":"https://upload.wikimedia.org/wikipedia/en/8/8c/Pretty_Woman.jpg"},{"name":"Mrs. Doubtfire","rarity":"common","id":"mrs-doubtfire","subtitle":"Musical","details":"The film's devoted nanny arrived on stage in 2021, with Rob McClure racing through rapid-fire costume changes.","image":"https://upload.wikimedia.org/wikipedia/en/9/93/DoubtfireMusicalLogo.webp"},{"name":"The Great Gatsby","rarity":"common","id":"the-great-gatsby","subtitle":"Musical","details":"F. Scott Fitzgerald's Jazz Age novel reached the Broadway Theatre in 2024 in a lavish musical adaptation.","image":"https://upload.wikimedia.org/wikipedia/en/7/7d/TheGreatGatsbyBwayPoster.jpg"},{"name":"Back to the Future","rarity":"common","id":"back-to-the-future","subtitle":"Musical","details":"The time-travel film's DeLorean took flight when the musical transferred from the West End to Broadway in 2023.","image":"https://upload.wikimedia.org/wikipedia/en/e/e2/BackToTheFutureMusicalPoster.jpg"},{"name":"Some Like It Hot","rarity":"common","id":"some-like-it-hot","subtitle":"Musical","details":"The classic cross-dressing caper was reset and rescored by Marc Shaiman and Scott Wittman for Broadway in 2022.","image":"https://upload.wikimedia.org/wikipedia/en/6/65/Some_Like_It_Hot_Broadway.jpg"},{"name":"Shucked","rarity":"common","id":"shucked","subtitle":"Musical","details":"An original corn-fed comedy in 2023, the musical stood out as a rarity among film-inspired new shows.","image":"https://upload.wikimedia.org/wikipedia/en/3/3e/Shucked_poster.jpg"},{"name":"Suffs","rarity":"common","id":"suffs","subtitle":"Musical","details":"Shaina Taub wrote the book and score and starred in her 2024 musical about American suffragists.","image":"https://upload.wikimedia.org/wikipedia/en/a/a5/SuffsBroadwayPoster.jpg"},{"name":"Death Becomes Her","rarity":"common","id":"death-becomes-her","subtitle":"Musical","details":"The film's feuding, death-defying rivals took over the Lunt-Fontanne Theatre in the 2024 musical adaptation.","image":"https://upload.wikimedia.org/wikipedia/en/9/96/Death_Becomes_Her_Broadway_in_Chicago_Poster_2024.jpg"},{"name":"Hell's Kitchen","rarity":"common","id":"hell-s-kitchen","subtitle":"Musical","details":"Alicia Keys built the 2024 coming-of-age musical from her own songs and her Manhattan Plaza upbringing.","image":"https://upload.wikimedia.org/wikipedia/en/3/3d/Hell%27sKitchenBroadwayPoster.jpg"},{"name":"The Outsiders","rarity":"common","id":"the-outsiders","subtitle":"Musical","details":"S.E. Hinton's greasers and socs clashed in the 2024 adaptation, which went on to win Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/9/9a/The_Outsiders_Broadway_Poster.jpg"},{"name":"Water for Elephants","rarity":"common","id":"water-for-elephants","subtitle":"Musical","details":"The circus novel reached Broadway in 2024 with real acrobats woven into its traveling-show cast.","image":"https://upload.wikimedia.org/wikipedia/en/7/77/WaterForElephantsMusicalPoster.webp"},{"name":"The Full Monty","rarity":"common","id":"the-full-monty","subtitle":"Musical","details":"Sheffield steelworkers relocated to Buffalo staged a strip show in the 2000 film adaptation, David Yazbek's first Broadway score.","image":"https://upload.wikimedia.org/wikipedia/en/0/09/TheFullMontyMusicalLogo.png"},{"name":"The Most Happy Fella","rarity":"common","id":"the-most-happy-fella","subtitle":"Musical","details":"Frank Loesser's 1956 Napa Valley romance was so lushly sung that it bordered on opera in scope and feeling.","image":"https://upload.wikimedia.org/wikipedia/en/f/fd/Mosthappyfella.jpg"},{"name":"Li'l Abner","rarity":"common","id":"li-l-abner","subtitle":"Musical","details":"The comic strip's Dogpatch came to the stage in 1956, hillbilly satire and all, in a broad spoof of American politics.","image":"https://upload.wikimedia.org/wikipedia/commons/2/26/Li%27l_Abner_Broadway_postcard.jpg"},{"name":"Redhead","rarity":"common","id":"redhead","subtitle":"Musical","details":"Gwen Verdon led the 1959 mystery set in Jack-the-Ripper-era London, and the production won Best Musical.","image":"https://upload.wikimedia.org/wikipedia/en/a/aa/Redhead.png"},{"name":"Irma La Douce","rarity":"common","id":"irma-la-douce","subtitle":"Musical","details":"The 1960 Parisian import had a twist: its score was sung, while the source play it came from was not.","image":"https://upload.wikimedia.org/wikipedia/commons/8/81/Irma_la_Duoce-1959.jpg"},{"name":"110 in the Shade","rarity":"common","id":"110-in-the-shade","subtitle":"Musical","details":"The Fantasticks team musicalized The Rainmaker for 1963, setting a drought-country romance to song.","image":"https://upload.wikimedia.org/wikipedia/en/7/7d/110_In_the_Shade_CD_Cover.jpg"},{"name":"Flora, the Red Menace","rarity":"common","id":"flora-the-red-menace","subtitle":"Musical","details":"Kander and Ebb's first Broadway score arrived in 1965 and carried Liza Minnelli's Broadway debut.","image":"https://upload.wikimedia.org/wikipedia/en/8/80/Flora_the_Red_Menace_%28poster%29.jpg"},{"name":"Golden Boy","rarity":"common","id":"golden-boy","subtitle":"Musical","details":"Sammy Davis Jr. played a boxer fighting his way out of Harlem to fame in the 1964 musical drama.","image":"https://upload.wikimedia.org/wikipedia/en/4/42/GoldenBoy1.JPG"},{"name":"Do Re Mi","rarity":"common","id":"do-re-mi","subtitle":"Musical","details":"Jule Styne, Betty Comden and Adolph Green tackled the jukebox racket in 1960, with Phil Silvers leading the hustle.","image":"https://upload.wikimedia.org/wikipedia/en/7/75/Do_re_silvers.JPG"},{"name":"On the Twentieth Century","rarity":"common","id":"on-the-twentieth-century","subtitle":"Musical","details":"Cy Coleman's 1978 madcap train operetta crammed romance and show business aboard one luxury express.","image":"https://upload.wikimedia.org/wikipedia/en/5/5f/TwentiethCentury.jpg"},{"name":"Mack & Mabel","rarity":"common","id":"mack-and-mabel","subtitle":"Musical","details":"Jerry Herman's 1974 romance of silent-film makers was a flop that later earned a devoted reputation for its score.","image":"https://upload.wikimedia.org/wikipedia/en/6/66/Mack_1974.jpg"},{"name":"A Streetcar Named Desire","rarity":"legendary","id":"a-streetcar-named-desire","subtitle":"Play","details":"Tennessee Williams' 1947 drama sent Blanche DuBois to New Orleans, where Marlon Brando's Stanley clashed with Jessica Tandy's Blanche.","image":"https://cdn11.bigcommerce.com/s-rmoyg9wwxo/images/stencil/1280w/products/130/8051/streetcar-named-desire-playbill-poster-lithograph__89414.1671449138.jpg?c=2"},{"name":"Death of a Salesman","rarity":"legendary","id":"death-of-a-salesman","subtitle":"Play","details":"Arthur Miller's 1949 tragedy followed Willy Loman's failing pursuit of success and went on to win the Pulitzer Prize for Drama.","image":"https://assets.playbill.com/editorial/_embeddedGallerySize/a41a23929f5bf845f50ed62c23c05cc4-Death-Of-A-Salesman-Playbill-08-49.jpg"},{"name":"Who's Afraid of Virginia Woolf?","rarity":"legendary","id":"who-s-afraid-of-virginia-woolf","subtitle":"Play","details":"Edward Albee's 1962 drama trapped George and Martha in a night of drinking, guests and cruel games that reshaped American theatre.","image":"https://upload.wikimedia.org/wikipedia/en/3/30/Who%27s_Afraid_of_Virginia_Woolf.jpg"},{"name":"Long Day's Journey into Night","rarity":"legendary","id":"long-day-s-journey-into-night","subtitle":"Play","details":"Eugene O'Neill's autobiographical 1956 premiere laid bare the Tyrone family's addictions and regrets, winning a posthumous Pulitzer.","image":"https://upload.wikimedia.org/wikipedia/en/f/fa/Long_Day%27s_Journey_into_Night_1956.jpg"},{"name":"Our Town","rarity":"epic","id":"our-town","subtitle":"Play","details":"Thornton Wilder's 1938 portrait of Grover's Corners used a bare stage and a Stage Manager to trace ordinary life, love and loss.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Craven-Our-Town-1938.jpg/500px-Craven-Our-Town-1938.jpg"},{"name":"The Glass Menagerie","rarity":"epic","id":"the-glass-menagerie","subtitle":"Play","details":"Tennessee Williams' 1945 memory play recalled Tom Wingfield's family and the Gentleman Caller's visit that briefly raised their hopes.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d5/The_Glass_Menagerie_%28Broadway%2C_1945%29_1.jpg"},{"name":"Cat on a Hot Tin Roof","rarity":"epic","id":"cat-on-a-hot-tin-roof","subtitle":"Play","details":"Tennessee Williams' 1955 drama set Brick and Maggie against Big Daddy's birthday gathering, where lies about health and inheritance surfaced.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Cat-on-a-Hot-Tin-Roof-Gazzara-1.jpg/500px-Cat-on-a-Hot-Tin-Roof-Gazzara-1.jpg"},{"name":"The Crucible","rarity":"epic","id":"the-crucible","subtitle":"Play","details":"Arthur Miller's 1953 Salem witch-trial drama drew a pointed parallel with McCarthy-era accusations and the cost of mass hysteria.","image":"https://upload.wikimedia.org/wikipedia/en/7/75/Cruciblecover.jpg"},{"name":"A Raisin in the Sun","rarity":"epic","id":"a-raisin-in-the-sun","subtitle":"Play","details":"Lorraine Hansberry's 1959 drama followed the Younger family's move toward a new home; it was the first play by a Black woman on Broadway.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fd/A_Raisin_in_the_Sun_1959.JPG"},{"name":"Angels in America","rarity":"epic","id":"angels-in-america","subtitle":"Play","details":"Tony Kushner's two-part 1993 epic mixed AIDS, religion and politics in Reagan-era America and won the Pulitzer Prize for Drama.","image":"https://upload.wikimedia.org/wikipedia/en/f/f1/Angels_in_America%2C_Millennium_Approaches_%281993%29_poster.jpg"},{"name":"Fences","rarity":"epic","id":"fences","subtitle":"Play","details":"August Wilson's 1987 drama centred garbageman and former ballplayer Troy Maxson; it won the Pulitzer Prize and the Tony for Best Play.","image":"assets/sets/compress/stage__fences.webp"},{"name":"Inherit the Wind","rarity":"rare","id":"inherit-the-wind","subtitle":"Play","details":"Jerome Lawrence and Robert E. Lee's 1955 courtroom drama fictionalised the Scopes trial as a clash over science, faith and free thought.","image":"https://theatre.utk.edu/wp-content/uploads/2026/03/ITW_5.jpg"},{"name":"The Diary of Anne Frank","rarity":"rare","id":"the-diary-of-anne-frank","subtitle":"Play","details":"Frances Goodrich and Albert Hackett's 1955 adaptation staged Anne Frank's years in hiding; it won the Pulitzer and the Tony for Best Play.","image":"https://www.gabriellalombardo.com/wp-content/uploads/2019/04/TheDiaryofAnneFrank-735x865.jpg"},{"name":"A Man for All Seasons","rarity":"rare","id":"a-man-for-all-seasons","subtitle":"Play","details":"Robert Bolt's 1961 drama showed Thomas More refusing to bend his conscience for Henry VIII and won the Tony Award for Best Play.","image":"https://upload.wikimedia.org/wikipedia/commons/7/72/A_Man_For_All_Seasons_Prog_1960.jpg"},{"name":"The Odd Couple","rarity":"rare","id":"the-odd-couple","subtitle":"Play","details":"Neil Simon's 1965 comedy paired slovenly Oscar Madison with fussy Felix Ungar as mismatched roommates, in a production directed by Mike Nichols.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cd/Walter_Matthau_Art_Carney_The_Odd_Couple_Broadway_1965.JPG"},{"name":"Amadeus","rarity":"rare","id":"amadeus","subtitle":"Play","details":"Peter Shaffer's 1980 drama let rival composer Antonio Salieri confess his obsession with Mozart; it won the Tony Award for Best Play.","image":"https://upload.wikimedia.org/wikipedia/en/7/76/Amadeus_Playbill.jpg"},{"name":"Glengarry Glen Ross","rarity":"rare","id":"glengarry-glen-ross","subtitle":"Play","details":"David Mamet's 1984 drama followed desperate Chicago real-estate salesmen competing for leads and won the Pulitzer Prize for Drama.","image":"https://upload.wikimedia.org/wikipedia/en/4/49/Glengarry_Glen_Ross_Poster.jpg"},{"name":"Doubt","rarity":"rare","id":"doubt","subtitle":"Play","details":"John Patrick Shanley's 2005 drama set a nun's suspicions against a priest in a Bronx parish school; it won the Pulitzer and Best Play Tony.","image":"https://www.tonyawards.com/media/images/b_p_Doubt.max-1400x1000.jpg"},{"name":"August: Osage County","rarity":"rare","id":"august-osage-county","subtitle":"Play","details":"Tracy Letts' 2007 family drama gathered the Westons in Oklahoma after a disappearance; it won the Pulitzer Prize and the Tony for Best Play.","image":"https://upload.wikimedia.org/wikipedia/en/0/04/August-osagecounty.jpg"},{"name":"Harry Potter and the Cursed Child","rarity":"rare","id":"harry-potter-and-the-cursed-child","subtitle":"Play","details":"Jack Thorne's two-part 2018 spectacle followed Harry's son Albus and Scorpio Malfoy through time, winning Broadway's Tony for Best Play.","image":"https://upload.wikimedia.org/wikipedia/en/8/87/Cursed_Child_new_poster.jpg"},{"name":"Sleuth","rarity":"rare","id":"sleuth","subtitle":"Play","details":"Anthony Shaffer's 1970 thriller turned a mystery writer and his wife's lover into players in an elaborate game; it won the Tony for Best Play.","image":"https://upload.wikimedia.org/wikipedia/en/5/5e/Sleuth-1970-FE.jpg"},{"name":"You Can't Take It with You","rarity":"uncommon","id":"you-can-t-take-it-with-you","subtitle":"Play","details":"George S. Kaufman and Moss Hart's 1936 comedy celebrated the eccentric Sycamore household and won the Pulitzer Prize for Drama.","image":"https://i.ebayimg.com/images/g/0~4AAOSwrsNnJpp6/s-l600.webp"},{"name":"Arsenic and Old Lace","rarity":"uncommon","id":"arsenic-and-old-lace","subtitle":"Play","details":"Joseph Kesselring's 1941 dark comedy revealed that the kindly Brewster aunts were poisoning lonely lodgers with their elderberry wine.","image":"https://upload.wikimedia.org/wikipedia/en/5/52/Arsenic-and-Old-Lace-1941-FE.jpg"},{"name":"Harvey","rarity":"uncommon","id":"harvey","subtitle":"Play","details":"Mary Chase's 1944 comedy followed Elwood P. Dowd and the tall invisible rabbit he called his friend; it won the Pulitzer Prize for Drama.","image":"https://darren-mediafiles-singapore.s3.amazonaws.com/media/projects/harvey.png"},{"name":"Born Yesterday","rarity":"uncommon","id":"born-yesterday","subtitle":"Play","details":"Garson Kanin's 1946 comedy sent ex-showgirl Billie Dawn to Washington, where Judy Holliday's character quickly outlearned her corrupt tycoon.","image":"https://www.bornyesterdayonbroadway.com/images/static_playbill.jpg"},{"name":"The Philadelphia Story","rarity":"uncommon","id":"the-philadelphia-story","subtitle":"Play","details":"Philip Barry's 1939 comedy of socialite Tracy Lord's remarriage was written for Katharine Hepburn and restored her standing as a star.","image":"https://imgc.artprintimages.com/img/print/the-philadelphia-story_u-l-q1hjwfh0.jpg"},{"name":"The Miracle Worker","rarity":"uncommon","id":"the-miracle-worker","subtitle":"Play","details":"William Gibson's 1959 drama showed teacher Anne Sullivan breaking through to young Helen Keller; it won the Tony Award for Best Play.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c7/Anne_Bancroft_Patty_Duke_Miracle_Worker_1_1960.jpg"},{"name":"Plaza Suite","rarity":"uncommon","id":"plaza-suite","subtitle":"Play","details":"Neil Simon's 1968 comedy placed three different couples in the same Plaza Hotel suite, with Maureen Stapleton in the original Broadway cast.","image":"https://i.ebayimg.com/images/g/B2MAAOSwJCJlWkV4/s-l600.webp"},{"name":"The Sunshine Boys","rarity":"uncommon","id":"the-sunshine-boys","subtitle":"Play","details":"Neil Simon's 1972 comedy reunited a retired vaudeville double act whose members could barely stand each other offstage.","image":"https://assets.playbill.com/editorial/_galleryFull/30083298c26660656f23589d0602543a-The-Sunshine-Boys-Playbill-01-98-ns.jpg"},{"name":"Equus","rarity":"uncommon","id":"equus","subtitle":"Play","details":"Peter Shaffer's 1974 drama sent a psychiatrist to probe a stable boy who had blinded horses; it won the Tony Award for Best Play.","image":"https://old.bruxellons.be/Images/LogoShow150200/Equus1973London.jpg"},{"name":"Deathtrap","rarity":"uncommon","id":"deathtrap","subtitle":"Play","details":"Ira Levin's 1978 thriller about a blocked playwright plotting around a student's script became a long-running Broadway comedy-thriller.","image":"https://www.twentiethcenturyposters.com/cdn/shop/files/DSC6894template.jpg?v=1732015897"},{"name":"Children of a Lesser God","rarity":"uncommon","id":"children-of-a-lesser-god","subtitle":"Play","details":"Mark Medoff's 1980 drama, partly performed in sign language, centred a deaf former student and her teacher; it won the Tony for Best Play.","image":"https://images.ctfassets.net/6pezt69ih962/3l627sAjBwQ9TFHq3V4tQN/71a7442d05a60f6b7614791bca5a0052/1516660779799_COG-0017M-TodayTix-480x720px-v2.jpg?h=540&f=faces&fit=fill&fm=webp&q=90"},{"name":"Brighton Beach Memoirs","rarity":"uncommon","id":"brighton-beach-memoirs","subtitle":"Play","details":"Neil Simon's 1983 comedy introduced teenager Eugene Jerome and his extended Brooklyn family in 1937, opening his Brighton Beach trilogy.","image":"assets/sets/compress/stage__brighton-beach-memoirs.webp"},{"name":"Lost in Yonkers","rarity":"uncommon","id":"lost-in-yonkers","subtitle":"Play","details":"Neil Simon's 1991 drama placed two boys with their formidable grandmother during wartime and won the Pulitzer Prize for Drama.","image":"https://www.historichideaways.com/wp-content/uploads/2023/06/LostYonkers_Poster_24_x36_-scaled-1.jpg"},{"name":"The Heidi Chronicles","rarity":"uncommon","id":"the-heidi-chronicles","subtitle":"Play","details":"Wendy Wasserstein's 1989 drama tracked art historian Heidi Holland alongside the women's movement; it won the Pulitzer Prize for Drama.","image":"assets/sets/compress/stage__the-heidi-chronicles.webp"},{"name":"Six Degrees of Separation","rarity":"uncommon","id":"six-degrees-of-separation","subtitle":"Play","details":"John Guare's 1990 drama followed a polished young impostor who talked his way into the homes of wealthy Fifth Avenue art dealers.","image":"https://dpvintageposters.com/cgi-local/db_images/posters/cache/6685-image-1200-1200-fit.jpg"},{"name":"Proof","rarity":"uncommon","id":"proof","subtitle":"Play","details":"David Auburn's 2000 drama asked whether a late mathematician's daughter inherited his genius or his illness; it won Pulitzer and Best Play honours.","image":"https://shubert.nyc/media/388016/proof-broadway-show-tickets-2-260317.jpg?width=357.2222222222223&height=500"},{"name":"Take Me Out","rarity":"uncommon","id":"take-me-out","subtitle":"Play","details":"Richard Greenberg's 2003 drama examined a baseball star's decision to come out publicly; it won the Tony Award for Best Play.","image":"https://theatricalindex.com/media_cache/media/subshows/take-me-out/take-me-out-revival/memberlogo/logo.jpg"},{"name":"To Kill a Mockingbird","rarity":"uncommon","id":"to-kill-a-mockingbird","subtitle":"Play","details":"Aaron Sorkin's 2018 adaptation of Harper Lee's novel centred Atticus Finch in Depression-era Alabama and became a record-grossing American play.","image":"https://i.pinimg.com/originals/b0/81/66/b08166c12f3dce7a61274b3b2e4fb66a.jpg"},{"name":"Life with Father","rarity":"common","id":"life-with-father","subtitle":"Play","details":"Howard Lindsay and Russel Crouse's 1939 family comedy ran 3,224 performances, the longest run for a straight play in Broadway history.","image":"https://upload.wikimedia.org/wikipedia/commons/7/79/Life_With_Father_1954.JPG"},{"name":"Barefoot in the Park","rarity":"common","id":"barefoot-in-the-park","subtitle":"Play","details":"Neil Simon's 1963 comedy sent newlyweds, including Robert Redford's Paul, into a cramped sixth-floor walk-up apartment in New York.","image":"https://upload.wikimedia.org/wikipedia/en/f/f6/Image-BarefootPoster.jpg"},{"name":"Mister Roberts","rarity":"common","id":"mister-roberts","subtitle":"Play","details":"Thomas Heggen and Joshua Logan's 1948 drama starred Henry Fonda as a cargo-ship officer and was the first winner of the Best Play Tony.","image":"https://upload.wikimedia.org/wikipedia/commons/3/35/Mister_Roberts_1950.jpg"},{"name":"Picnic","rarity":"common","id":"picnic","subtitle":"Play","details":"William Inge's 1953 drama brought a handsome drifter into a Kansas town over Labor Day weekend and won the Pulitzer Prize for Drama.","image":"https://i.ebayimg.com/images/g/9qUAAOSw~mtj7lmX/s-l600.webp"},{"name":"The Seven Year Itch","rarity":"common","id":"the-seven-year-itch","subtitle":"Play","details":"George Axelrod's 1952 comedy imagined a married publisher alone in New York for the summer, tempted by the neighbour upstairs.","image":"https://upload.wikimedia.org/wikipedia/commons/8/82/Tom_Ewell_-_1952.jpg"},{"name":"Butterflies Are Free","rarity":"common","id":"butterflies-are-free","subtitle":"Play","details":"Leonard Gershe's 1969 drama paired a young blind songwriter in New York with his free-spirited neighbour in a gentle, long-running hit.","image":"https://i.ebayimg.com/images/g/-OsAAOSwv2JXwtpg/s-l600.webp"},{"name":"Same Time, Next Year","rarity":"common","id":"same-time-next-year","subtitle":"Play","details":"Bernard Slade's 1975 two-character comedy met a couple once a year at the same inn across decades, running 1,453 performances on Broadway.","image":"https://cdn11.bigcommerce.com/s-i6magi2txm/images/stencil/640w/products/823/2935/sametimenextyearcoveraug1975__71736.1502113809.jpg?c=2"},{"name":"Master Harold... and the Boys","rarity":"common","id":"master-harold-and-the-boys","subtitle":"Play","details":"Athol Fugard's 1982 drama set a white schoolboy and two Black waiters in a Port Elizabeth tea room, exposing apartheid in miniature.","image":"https://upload.wikimedia.org/wikipedia/en/9/96/Master_Harold_and_the_Boys_Penguin.jpg"},{"name":"Biloxi Blues","rarity":"common","id":"biloxi-blues","subtitle":"Play","details":"Neil Simon's 1985 comedy sent Eugene Jerome through Army basic training in Mississippi in 1943; it won the Tony Award for Best Play.","image":"https://i.ebayimg.com/images/g/vJ0AAeSwagRn8eH6/s-l1600.jpg"},{"name":"The Play That Goes Wrong","rarity":"common","id":"the-play-that-goes-wrong","subtitle":"Play","details":"Written by Henry Lewis, Jonathan Sayer and Henry Shields, this 2017 transfer staged a murder mystery collapsing scene by scene around its cast.","image":"https://www.nyctourism.com/_next/image/?url=https%3A%2F%2Fnyc-tourism-public.s3.amazonaws.com%2Fprograms%2FThe-Play-That-Goes-Wrong-Key-Art-Off-Broadway-Manhattan-NYC-Courtesy.jpg&w=1080&q=75"},{"name":"God of Carnage","rarity":"common","id":"god-of-carnage","subtitle":"Play","details":"Yasmina Reza's 2009 comedy watched two sets of parents meet about a playground fight and behave far worse; it won the Tony for Best Play.","image":"https://cdn-imgix.headout.com/media/images/4690047f260594ea9ecc61f01274d0e7-24115-london-god-of-carnage-01.jpg?auto=compress%2Cformat&w=1188&h=742.5&q=112.5&crop=faces&fit=crop"},{"name":"Red","rarity":"common","id":"red","subtitle":"Play","details":"John Logan's 2010 two-hander placed painter Mark Rothko and his young assistant before huge canvases; it won the Tony Award for Best Play.","image":"https://images.ctfassets.net/6pezt69ih962/6Bow0VEdfkq758C1ceRU9X/e464faac56f1027d200a5c47e2a0179e/1523449399366_RED18_Q1_015_TODAYTIX_480x720.jpg?h=480&fm=webp&q=90"},{"name":"Clybourne Park","rarity":"common","id":"clybourne-park","subtitle":"Play","details":"Bruce Norris' 2012 drama revisited the house from A Raisin in the Sun in 1959 and 2009, winning the Pulitzer Prize and the Tony for Best Play.","image":"assets/sets/stage/clybourne-park.jpg"},{"name":"The Humans","rarity":"common","id":"the-humans","subtitle":"Play","details":"Stephen Karam's 2016 drama gathered a family for Thanksgiving in a Chinatown duplex haunted by small fears; it won the Tony for Best Play.","image":"https://www.tonyawards.com/media/images/r_Humans_poster.max-1400x1000.jpg"},{"name":"Sweat","rarity":"common","id":"sweat","subtitle":"Play","details":"Lynn Nottage's 2017 drama followed factory workers in Reading, Pennsylvania, as layoffs strained old friendships; it won the Pulitzer Prize.","image":"https://cloudinary-assets.dostuffmedia.com/res/dostuff-media/image/upload/event-10163792/1543677723.jpg"},{"name":"Oslo","rarity":"common","id":"oslo","subtitle":"Play","details":"J.T. Rogers' 2017 drama dramatised the secret Norwegian back channel behind the Oslo peace accords and won the Tony Award for Best Play.","image":"https://cs-tm-prod-photos.azureedge.net/123779.jpg"},{"name":"The Ferryman","rarity":"common","id":"the-ferryman","subtitle":"Play","details":"Jez Butterworth's 2018 drama set a County Armagh family harvest gathering against the Troubles; it won the Tony Award for Best Play.","image":"https://broadwaydirect.com/wp-content/uploads/2018/03/Unknown-4-1600x450.jpeg"},{"name":"Stereophonic","rarity":"common","id":"stereophonic","subtitle":"Play","details":"David Adjmi's 2024 drama recreated a 1970s rock band's fraught studio sessions and became the most Tony-nominated play in history.","image":"https://www.picclickimg.com/ozgAAOSwF61mVO9c/Cast-Signed-STEREOPHONIC-Broadway-Poster-Windowcard.webp"},{"name":"Oh, Mary!","rarity":"common","id":"oh-mary","subtitle":"Play","details":"Cole Escola's 2024 comedy reimagined Mary Todd Lincoln as a frustrated former cabaret performer in the weeks before her husband's assassination.","image":"https://playbillstore.com/cdn/shop/files/Oh-Mary-Playbill-2026-06-01_HR_1.jpg?v=1779908275&width=700"},{"name":"A Doll's House, Part 2","rarity":"common","id":"a-doll-s-house-part-2","subtitle":"Play","details":"Lucas Hnath's 2017 sequel brought Ibsen's Nora back, fifteen years on, through the doorway she had famously slammed behind her.","image":"https://shubert.nyc/media/2207/dolls-house-part-2-072617.jpg?width=371&height=520"},{"name":"Slave Play","rarity":"common","id":"slave-play","subtitle":"Play","details":"Jeremy O. Harris' 2019 drama used antebellum role-play to confront race and desire, earning a record-tying twelve Tony nominations.","image":"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiGXJirVaQj0dSHdI8Sa51LrVQqWkfMF78UOIiUhCm_BHObo8UcrW8w9t5v-TLneeNgVtgimwG6XycA42ek6QVuG-uU5sakkeAxIrNfblyJ9XVs3j8RJNaKjPcX8WlfZYHbs7w9gcybUvqk/s400/111701-13.jpg"},{"name":"Leopoldstadt","rarity":"common","id":"leopoldstadt","subtitle":"Play","details":"Tom Stoppard's 2022 Broadway drama traced a large Viennese Jewish family across half a century; it won the Tony Award for Best Play.","image":"assets/sets/compress/stage__leopoldstadt.webp"},{"name":"Wait Until Dark","rarity":"common","id":"wait-until-dark","subtitle":"Play","details":"Frederick Knott's 1966 thriller pitted a blind woman, Susy, against con men searching her apartment for a doll filled with contraband.","image":"https://assets.playbill.com/playbill-covers/667e1e5670adad51af299616fe6ca959-Wait-Until-Dark-Playbill-02-66.jpg"},{"name":"The History Boys","rarity":"common","id":"the-history-boys","subtitle":"Play","details":"Alan Bennett's 2006 Broadway drama followed eight grammar-school boys aiming for Oxford and Cambridge; it won the Tony for Best Play.","image":"https://www.theexeterdaily.co.uk/sites/default/files/styles/654w/public/field/image/History%20Boys.%20Photo%20Credit%20Matt%20Martin%20Photography%20%284%29.jpg?itok=uY8Kv-zH"},{"name":"Frost/Nixon","rarity":"common","id":"frost-nixon","subtitle":"Play","details":"Peter Morgan's 2007 drama turned David Frost's interviews with Richard Nixon into a contest, led on Broadway by Frank Langella as Nixon.","image":"https://artware.berlin/assets/images/plakat-29-800x1130-800x1130.jpg"},{"name":"The Lehman Trilogy","rarity":"common","id":"the-lehman-trilogy","subtitle":"Play","details":"Stefano Massini's 2021 Broadway epic told 163 years of the Lehman family and its bank across three acts, winning the Tony for Best Play.","image":"https://seatplan.com/cdn/images/c/production/lehman-trilogy-broadway-hero-710wx355h-1638193960.webp"},{"name":"War Horse","rarity":"common","id":"war-horse","subtitle":"Play","details":"Nick Stafford's 2011 adaptation sent Joey, a life-size puppet horse, from Devon to the Western Front in a Lincoln Center spectacle.","image":"https://dxan6czxprkid.cloudfront.net/images/_1420xAUTO_crop_center-center_none/war-horse-featured-art-1420x1065.jpg"},{"name":"The Curious Incident of the Dog in the Night-Time","rarity":"common","id":"the-curious-incident-of-the-dog-in-the-night-time","subtitle":"Play","details":"Simon Stephens' 2014 adaptation followed teenager Christopher investigating a neighbour's dead dog; it won the Tony for Best Play.","image":"https://utahtheatrebloggers.com/wp-content/uploads/2015/11/Curious-Incident-poster-Broadway.jpg"},{"name":"The Elephant Man","rarity":"common","id":"the-elephant-man","subtitle":"Play","details":"Bernard Pomerance's 1979 drama portrayed Joseph Merrick's life in Victorian London and won the Tony Award for Best Play.","image":"https://images.nypl.org/index.php?id=2025406&t=w"},{"name":"The Man Who Came to Dinner","rarity":"common","id":"the-man-who-came-to-dinner","subtitle":"Play","details":"George S. Kaufman and Moss Hart's 1939 comedy stranded the imperious critic Sheridan Whiteside as an unwelcome houseguest after a fall.","image":"https://collections.mcny.org/Assets/V2/ChFNTllTNTAwMDAwMDAwMDEwNhIDVFIxGhlcVFIxXGZcOVxlXGJcTTJZMjgzMzUuanBnIgQIARAPQAE-~/2F3408RSU34/lzboUuwD3TQ_cbUN/M2Y28335.jpg"},{"name":"The Teahouse of the August Moon","rarity":"common","id":"the-teahouse-of-the-august-moon","subtitle":"Play","details":"John Patrick's 1953 comedy let an Okinawan village gently outwit its American occupiers; it won the Pulitzer and the Tony for Best Play.","image":"https://32-1rarebooks.cdn.bibliopolis.com/pictures/11232351.jpeg?auto=webp&v=1700942289"}]});
